<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { cleanCart, listAppSlots, listCart, payOrder, submitOrder } from '../../api/app'
import type { PickupSlot, ShoppingCart } from '../../api/types'
const router = useRouter(); const items = ref<ShoppingCart[]>([]); const slots = ref<PickupSlot[]>([]); const slotId = ref<number>(); const loading = ref(true); const submitting = ref(false); const pending = ref<{ id: number; orderNumber: string; pickupCode: string } | null>(null); const paying = ref(false); const slotDate = ref(new Date().toLocaleDateString('sv-SE'))
const total = computed(() => items.value.reduce((sum, item) => sum + Number(item.amount) * item.number, 0)); const stallId = computed(() => items.value[0]?.stallId)
async function loadSlots() { if (!stallId.value) return; slots.value = await listAppSlots(stallId.value, slotDate.value) }
async function load() { loading.value = true; try { items.value = await listCart(); if (stallId.value) { await loadSlots(); if (!slots.value.length) { slotDate.value = new Date(Date.now() + 86400000).toLocaleDateString('sv-SE'); await loadSlots() } } } finally { loading.value = false } }
async function submit() { if (!slotId.value) return ElMessage.warning('请选择取餐时段'); submitting.value = true; try { const order = await submitOrder({ slotId: slotId.value, payMethod: 3, remark: '学生端下单' }); pending.value = { id: order.id, orderNumber: order.orderNumber, pickupCode: order.pickupCode || '' }; ElMessage.success('订单已创建，请完成模拟支付'); await load() } catch (e) { ElMessage.error((e as Error).message) } finally { submitting.value = false } }
async function pay() { if (!pending.value) return; paying.value = true; try { await payOrder({ orderNumber: pending.value.orderNumber, payMethod: 3 }); ElMessage.success('支付成功，档口开始备餐'); router.replace(`/student/pickup/${pending.value.id}`) } catch (e) { ElMessage.error((e as Error).message) } finally { paying.value = false } }
async function clear() { await cleanCart(); await load() }
onMounted(load)
</script>
<template><div class="mobile-page cart-page"><h2 class="page-title">购物车</h2><p class="page-subtitle">同一档口一起下单，预约一个取餐时段。</p><div v-if="pending" class="page-card success-box"><strong>订单已创建</strong><span>订单号 {{ pending.orderNumber }}</span><span>取餐码 {{ pending.pickupCode }}</span><el-button type="primary" :loading="paying" @click="pay">模拟支付</el-button></div><div v-else v-loading="loading"><div v-if="!items.length" class="page-card empty">购物车还是空的，先去选一份饭吧。</div><template v-else><div class="page-card"><div v-for="item in items" :key="item.id" class="cart-item"><div><strong>{{ item.name }}</strong><span>× {{ item.number }}</span></div><b>¥{{ (Number(item.amount) * item.number).toFixed(2) }}</b></div><div class="total-line"><span>合计</span><strong>¥{{ total.toFixed(2) }}</strong></div></div><div class="page-card slot-card"><h3>选择取餐时段</h3><el-date-picker v-model="slotDate" type="date" value-format="YYYY-MM-DD" :clearable="false" style="width: 100%; margin-bottom: 10px" @change="loadSlots" /><div class="slot-grid"><button v-for="slot in slots" :key="slot.id" :class="{ active: slotId === slot.id, disabled: slot.remaining <= 0 }" :disabled="slot.remaining <= 0" @click="slotId = slot.id"><strong>{{ slot.startTime }} - {{ slot.endTime }}</strong><span>余 {{ slot.remaining }} / {{ slot.capacity }}</span></button></div><div v-if="!slots.length" class="empty">今天暂无可预约时段</div></div><div class="cart-actions"><el-button @click="clear">清空</el-button><el-button type="primary" size="large" :loading="submitting" @click="submit">提交订单</el-button></div></template></div></div></template>
<style scoped>.cart-item{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #edf0ee}.cart-item span{display:block;color:#87938f;font-size:11px;margin-top:4px}.total-line{display:flex;justify-content:space-between;padding-top:14px;font-size:16px}.slot-card{margin-top:12px}.slot-card h3{margin:0 0 12px;font-size:15px}.slot-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.slot-grid button{border:1px solid #d6e2dd;border-radius:4px;background:#fff;padding:11px 10px;text-align:left;cursor:pointer}.slot-grid button.active{border-color:#146b5c;background:#eef6f2;box-shadow:inset 0 0 0 1px #146b5c}.slot-grid button.disabled{opacity:.4;cursor:not-allowed}.slot-grid strong,.slot-grid span{display:block}.slot-grid strong{font-size:13px}.slot-grid span{color:#788984;font-size:10px;margin-top:5px}.cart-actions{position:sticky;bottom:68px;display:flex;justify-content:flex-end;gap:8px;margin-top:12px;padding:10px 0;background:linear-gradient(180deg,transparent,#f5f3ed 28%)}.success-box{display:grid;gap:8px;margin-bottom:12px;background:#f1f7f4;border-left:4px solid #146b5c}.success-box strong{font-size:17px;color:#146b5c}.success-box span{font-size:12px;color:#5e706b}</style>
